input.contents:
title: Political power runtime
max-visits: 1
new-page: false
on-arrival: {!

// MIKASA_POLITICAL_POWER_RUNTIME_BEGIN

var PP_PARTY_KEYS = ['D', 'I', 'C', 'G', 'H']
var PP_DISTRICT_IDS = [
    'Docks', 'Aurora', 'Vats', 'Railyard', 'Pitts', 'Limelight', 'Deeps',
]
var PP_CORP_IGS = ['soylent', 'magrail', 'brazos']
var PP_SYNDICATE_IGS = ['families', 'edges', 'sharks']
var PP_IG_IDS = PP_CORP_IGS.concat(PP_SYNDICATE_IGS)

var PP_DISTRICT_SEATS = 15
var PP_DISTRICT_MAJORITY = 8
var PP_EXEC_SEATS = 150
var PP_EXEC_MAJORITY = 76
/** Seats from one IG's party bloc that consume one bandwidth point. Tune later. */
var PP_BANDWIDTH_SEATS_PER_POINT = 5

/**
 * Home IGs for a district (boost >= 1.25 in election_runtime DISTRICT_IG_BOOST).
 * Multiple entries = none vote for pro-democratic reforms in that district.
 */
var PP_DISTRICT_HOME_IGS = {
    Docks: ['magrail'],
    Aurora: ['edges'],
    Vats: ['soylent'],
    Railyard: ['magrail'],
    Pitts: ['families', 'sharks'],
    Limelight: ['brazos'],
    Deeps: [],
}

var PP_IG_KIND = {
    soylent: 'corporate',
    magrail: 'corporate',
    brazos: 'corporate',
    families: 'syndicate',
    edges: 'syndicate',
    sharks: 'syndicate',
}

var PP_PARTY_IGS = {
    C: PP_CORP_IGS,
    G: PP_SYNDICATE_IGS,
}

function ppNum(v, fallback) {
    var n = Number(v)
    if (isNaN(n)) { return fallback != null ? fallback : 0 }
    return n
}

function ppSumSeats(seats) {
    var total = 0
    for (var i = 0; i < PP_PARTY_KEYS.length; i++) {
        total += ppNum(seats[PP_PARTY_KEYS[i]], 0)
    }
    return total
}

function ppCloneSeats(seats) {
    var out = {}
    for (var i = 0; i < PP_PARTY_KEYS.length; i++) {
        var k = PP_PARTY_KEYS[i]
        out[k] = ppNum(seats[k], 0)
    }
    return out
}

function ppReadDistrictSeats(districtId) {
    return {
        D: ppNum(Q[districtId + '_D'], 0),
        I: ppNum(Q[districtId + '_I'], 0),
        C: ppNum(Q[districtId + '_C'], 0),
        G: ppNum(Q[districtId + '_G'], 0),
        H: ppNum(Q[districtId + '_H'], 0),
    }
}

function ppReadExecutiveSeats() {
    return {
        D: ppNum(Q.Exec_D, 0),
        I: ppNum(Q.Exec_I, 0),
        C: ppNum(Q.Exec_C, 0),
        G: ppNum(Q.Exec_G, 0),
        H: ppNum(Q.Exec_H, 0),
    }
}

function ppHomeIgsForDistrict(districtId) {
    return (PP_DISTRICT_HOME_IGS[districtId] || []).slice()
}

function ppCommittedBandwidth(igId) {
    return ppNum(Q[igId + '_bandwidth_committed'], 0)
}

/** Free leverage slack for one IG after commitments. Attitude label is informational only. */
function ppFreeBandwidth(igId, opts) {
    opts = opts || {}
    var L = ppNum(Q[igId + '_leverage'], 0)
    var R = ppNum(Q[igId + '_reprisal'], 0)
    var committed = opts.committed != null ? ppNum(opts.committed, 0) : ppCommittedBandwidth(igId)
    if (opts.reprisalDelta) {
        R += ppNum(opts.reprisalDelta[igId], 0)
    }
    return Math.max(0, L - R - committed)
}

function ppBandwidthCostForSeats(seatsProvided) {
    var n = ppNum(seatsProvided, 0)
    if (n <= 0) { return 0 }
    return Math.max(1, Math.ceil(n / PP_BANDWIDTH_SEATS_PER_POINT))
}

function ppIsExecutiveGraceActive() {
    if (ppNum(Q.executive_control_grace_active, 0) === 1) { return true }
    var untilYear = ppNum(Q.executive_grace_until_year, 0)
    var untilMonth = ppNum(Q.executive_grace_until_month, 0)
    if (untilYear <= 0) { return false }
    var y = ppNum(Q.year, 2300)
    var m = ppNum(Q.month, 1)
    return y < untilYear || (y === untilYear && m <= untilMonth)
}

function ppMajorityForChamber(chamberId) {
    if (chamberId === 'executive') { return PP_EXEC_MAJORITY }
    return PP_DISTRICT_MAJORITY
}

function ppSeatsForChamber(chamberId, districtId) {
    if (chamberId === 'executive') { return ppReadExecutiveSeats() }
    return ppReadDistrictSeats(districtId)
}

/** Attribute party seats to IGs for bandwidth billing (v1 heuristic). */
function ppAttributePartySeatsToIgs(party, seatsUsed, districtId, opts) {
    opts = opts || {}
    var homeIgs = ppHomeIgsForDistrict(districtId)
    var igList = PP_PARTY_IGS[party] || []
    var out = {}
    if (seatsUsed <= 0 || !igList.length) { return out }

    if (party === 'C' && homeIgs.length && !opts.allowHomeCorpSeats) {
        var homeCorps = homeIgs.filter(function(ig) { return PP_IG_KIND[ig] === 'corporate' })
        if (homeCorps.length) {
            var nonHome = Math.max(0, seatsUsed - seatsUsed)
            if (opts.reformVote) {
                seatsUsed = nonHome
            } else if (opts.tolerationProp) {
                var homeShare = Math.min(seatsUsed, ppNum(opts.homeCorpSeatsHeld, seatsUsed))
                if (homeShare > 0) {
                    out[homeCorps[0]] = (out[homeCorps[0]] || 0) + homeShare
                }
                seatsUsed -= homeShare
            }
        }
    }

    if (party === 'G' && homeIgs.length && opts.reformVote) {
        var homeSynds = homeIgs.filter(function(ig) { return PP_IG_KIND[ig] === 'syndicate' })
        if (homeSynds.length) {
            seatsUsed = 0
        }
    }

    if (seatsUsed <= 0) { return out }

    var ranked = igList.slice()
    if (districtId && homeIgs.length) {
        ranked.sort(function(a, b) {
            var ah = homeIgs.indexOf(a) >= 0 ? 1 : 0
            var bh = homeIgs.indexOf(b) >= 0 ? 1 : 0
            return bh - ah
        })
    }

    var primary = ranked[0]
    out[primary] = (out[primary] || 0) + seatsUsed
    return out
}

function ppMergePayees(target, add) {
    var keys = Object.keys(add)
    for (var i = 0; i < keys.length; i++) {
        var ig = keys[i]
        target[ig] = (target[ig] || 0) + add[ig]
    }
    return target
}

function ppPayeesToList(payeesByIg) {
    var list = []
    var keys = Object.keys(payeesByIg)
    for (var i = 0; i < keys.length; i++) {
        var ig = keys[i]
        var seats = payeesByIg[ig]
        if (seats > 0) {
            list.push({ ig: ig, seats: seats, cost: ppBandwidthCostForSeats(seats) })
        }
    }
    return list
}

function ppCoalitionAffordable(payeesByIg, opts) {
    opts = opts || {}
    var keys = Object.keys(payeesByIg)
    for (var i = 0; i < keys.length; i++) {
        var ig = keys[i]
        var cost = ppBandwidthCostForSeats(payeesByIg[ig])
        if (ppFreeBandwidth(ig, opts) < cost) { return false }
    }
    return true
}

function ppNonDPartiesUsed(partyUse) {
    var used = []
    var keys = ['C', 'G', 'I']
    for (var i = 0; i < keys.length; i++) {
        var k = keys[i]
        if (ppNum(partyUse[k], 0) > 0) { used.push(k) }
    }
    return used.sort().join('+')
}

function ppPartiesDisjoint(partyUseA, partyUseB) {
    var keys = ['C', 'G', 'I']
    for (var i = 0; i < keys.length; i++) {
        var k = keys[i]
        if (ppNum(partyUseA[k], 0) > 0 && ppNum(partyUseB[k], 0) > 0) { return false }
    }
    return true
}

/**
 * Build one player coalition that uses D plus optional C/G/I blocs to reach majority.
 * partyUse: { C?, G?, I? } seat counts consumed from each bloc.
 */
function ppBuildCoalition(chamberId, districtId, partyUse, opts) {
    opts = opts || {}
    var majority = ppMajorityForChamber(chamberId)
    var available = ppSeatsForChamber(chamberId, districtId)
    var dSeats = available.D
    var used = { D: dSeats, C: 0, G: 0, I: 0, H: 0 }
    var payees = {}
    var keys = ['C', 'G', 'I']

    for (var i = 0; i < keys.length; i++) {
        var k = keys[i]
        var want = ppNum(partyUse[k], 0)
        var have = available[k]
        if (want <= 0) { continue }
        if (want > have) { return null }
        used[k] = want
        ppMergePayees(payees, ppAttributePartySeatsToIgs(k, want, districtId, opts))
    }

    var total = used.D + used.C + used.G + used.I
    if (total < majority) { return null }

    return {
        id: 'D+' + ppNonDPartiesUsed(used),
        chamberId: chamberId,
        districtId: districtId || null,
        partyUse: { D: used.D, C: used.C, G: used.G, I: used.I },
        seatTotal: total,
        payees: ppPayeesToList(payees),
        affordable: ppCoalitionAffordable(payees, opts),
    }
}

/** Minimal seat consumption from each bloc to reach majority given fixed D seats. */
function ppMinimalPartyUse(dSeats, majority, available, pattern) {
    var need = Math.max(0, majority - dSeats)
    var use = { C: 0, G: 0, I: 0 }
    if (need <= 0) { return use }

    var keys = pattern || ['C', 'G', 'I']
    for (var i = 0; i < keys.length; i++) {
        var k = keys[i]
        if (need <= 0) { break }
        var take = Math.min(need, ppNum(available[k], 0))
        use[k] = take
        need -= take
    }
    if (need > 0) { return null }
    return use
}

function ppEnumeratePlayerCoalitions(chamberId, districtId, opts) {
    opts = opts || {}
    var majority = ppMajorityForChamber(chamberId)
    var available = ppSeatsForChamber(chamberId, districtId)
    var dSeats = available.D
    var coalitions = []
    var seen = {}

    if (dSeats >= majority) {
        var outright = ppBuildCoalition(chamberId, districtId, { C: 0, G: 0, I: 0 }, opts)
        if (outright) { coalitions.push(outright) }
    }

    var patterns = [
        ['C'], ['G'], ['I'],
        ['C', 'G'], ['C', 'I'], ['G', 'I'],
        ['C', 'G', 'I'],
    ]

    for (var p = 0; p < patterns.length; p++) {
        var use = ppMinimalPartyUse(dSeats, majority, available, patterns[p])
        if (!use) { continue }
        var coalition = ppBuildCoalition(chamberId, districtId, use, opts)
        if (!coalition) { continue }
        if (seen[coalition.id]) { continue }
        seen[coalition.id] = 1
        coalitions.push(coalition)
    }

    return coalitions
}

function ppCorpCanGovernWithToleration(districtId) {
    var seats = ppReadDistrictSeats(districtId)
    var homeIgs = ppHomeIgsForDistrict(districtId)
    var homeCorps = homeIgs.filter(function(ig) { return PP_IG_KIND[ig] === 'corporate' })
    if (!homeCorps.length) { return { possible: false, seatTotal: seats.C } }

    var total = seats.C + seats.D
    return {
        possible: total >= PP_DISTRICT_MAJORITY,
        seatTotal: total,
        homeCorp: homeCorps[0],
        corpSeats: seats.C,
        demSeats: seats.D,
    }
}

function ppTolerationOfferEligible(districtId) {
    var seats = ppReadDistrictSeats(districtId)
    if (seats.C >= PP_DISTRICT_MAJORITY) {
        return { eligible: false, reason: 'corp_majority' }
    }
    var prop = ppCorpCanGovernWithToleration(districtId)
    if (!prop.possible) {
        return { eligible: false, reason: 'insufficient_seats' }
    }
    return {
        eligible: true,
        homeCorp: prop.homeCorp,
        corpSeats: prop.corpSeats,
        demSeats: prop.demSeats,
        governingSeats: prop.seatTotal,
    }
}

function ppCheckDistrictControl(districtId) {
    var seats = ppReadDistrictSeats(districtId)
    var coalitions = ppEnumeratePlayerCoalitions('district', districtId, {})
    var affordable = coalitions.filter(function(c) { return c.affordable })
    var toleration = ppTolerationOfferEligible(districtId)
    var corpMajority = seats.C >= PP_DISTRICT_MAJORITY

    var status = 'anarchy'
    if (affordable.length) {
        status = 'player'
    } else if (corpMajority) {
        status = 'corp'
    } else if (toleration.eligible) {
        status = 'toleration_offer'
    } else if (ppCorpCanGovernWithToleration(districtId).possible) {
        status = 'corp_with_toleration'
    }

    return {
        districtId: districtId,
        seats: seats,
        status: status,
        coalitions: coalitions,
        affordableCoalitions: affordable,
        tolerationOffer: toleration,
        corpMajority: corpMajority,
    }
}

function ppCheckExecutiveControl() {
    if (ppIsExecutiveGraceActive()) {
        return {
            chamberId: 'executive',
            status: 'player_grace',
            graceActive: true,
            coalitions: [],
            affordableCoalitions: [],
        }
    }

    var coalitions = ppEnumeratePlayerCoalitions('executive', null, {})
    var affordable = coalitions.filter(function(c) { return c.affordable })
    return {
        chamberId: 'executive',
        status: affordable.length ? 'player' : 'corp_flunky',
        graceActive: false,
        coalitions: coalitions,
        affordableCoalitions: affordable,
    }
}

function ppEnumerateReformVoteCoalitions(districtId) {
    var opts = { reformVote: true }
    return ppEnumeratePlayerCoalitions('district', districtId, opts)
        .filter(function(c) { return ppNum(c.partyUse.H, 0) === 0 })
}

function ppFindProDemocraticDualPaths(districtId) {
    var coalitions = ppEnumerateReformVoteCoalitions(districtId)
    var pairs = []

    for (var i = 0; i < coalitions.length; i++) {
        for (var j = i + 1; j < coalitions.length; j++) {
            var a = coalitions[i]
            var b = coalitions[j]
            if (!ppPartiesDisjoint(a.partyUse, b.partyUse)) { continue }
            if (!a.affordable || !b.affordable) { continue }
            pairs.push({ pathA: a, pathB: b })
        }
    }

    return {
        districtId: districtId,
        homeIgs: ppHomeIgsForDistrict(districtId),
        coalitions: coalitions,
        validPairs: pairs,
        possible: pairs.length > 0,
    }
}

function ppApplyReprisalDelta(reprisalByIg) {
    var delta = reprisalByIg || {}
    return { reprisalDelta: delta }
}

function ppCanMaintainControl(chamberId, districtId, opts) {
    opts = opts || {}
    var coalitions = ppEnumeratePlayerCoalitions(chamberId, districtId, opts)
    for (var i = 0; i < coalitions.length; i++) {
        if (coalitions[i].affordable) { return { ok: true, coalition: coalitions[i] }
        }
    }
    return { ok: false, coalition: null }
}

function ppCheckPostReformMaintenance(districtId, reprisalByIg, voteCoalitionId) {
    var opts = ppApplyReprisalDelta(reprisalByIg)
    var maintain = ppCanMaintainControl('district', districtId, opts)
    var voteCoalitions = ppEnumerateReformVoteCoalitions(districtId)
    var voteCoalition = null
    for (var i = 0; i < voteCoalitions.length; i++) {
        if (voteCoalitions[i].id === voteCoalitionId) {
            voteCoalition = voteCoalitions[i]
            break
        }
    }

    var voteIgs = {}
    if (voteCoalition) {
        for (var j = 0; j < voteCoalition.payees.length; j++) {
            voteIgs[voteCoalition.payees[j].ig] = 1
        }
    }

    var maintenanceIgs = {}
    if (maintain.ok && maintain.coalition) {
        for (var k = 0; k < maintain.coalition.payees.length; k++) {
            maintenanceIgs[maintain.coalition.payees[k].ig] = maintain.coalition.payees[k]
        }
    }

    var corpPostReformSupport = false
    var syndicatePostReformSupport = false
    var igKeys = Object.keys(maintenanceIgs)
    for (var m = 0; m < igKeys.length; m++) {
        var ig = igKeys[m]
        if (voteIgs[ig]) { continue }
        if (PP_IG_KIND[ig] === 'corporate') { corpPostReformSupport = true }
        if (PP_IG_KIND[ig] === 'syndicate') { syndicatePostReformSupport = true }
    }

    return {
        districtId: districtId,
        maintained: maintain.ok,
        maintenanceCoalition: maintain.coalition,
        voteCoalitionId: voteCoalitionId,
        achievements: {
            gotEmByTheShortHairs: corpPostReformSupport,
            anOfferTheyCantRefuse: syndicatePostReformSupport,
        },
    }
}

Q.ppFreeBandwidth = ppFreeBandwidth
Q.ppBandwidthCostForSeats = ppBandwidthCostForSeats
Q.ppHomeIgsForDistrict = ppHomeIgsForDistrict
Q.ppReadDistrictSeats = ppReadDistrictSeats
Q.ppReadExecutiveSeats = ppReadExecutiveSeats
Q.ppIsExecutiveGraceActive = ppIsExecutiveGraceActive
Q.ppTolerationOfferEligible = ppTolerationOfferEligible
Q.ppEnumeratePlayerCoalitions = ppEnumeratePlayerCoalitions
Q.ppCheckDistrictControl = ppCheckDistrictControl
Q.ppCheckExecutiveControl = ppCheckExecutiveControl
Q.ppFindProDemocraticDualPaths = ppFindProDemocraticDualPaths
Q.ppCanMaintainControl = ppCanMaintainControl
Q.ppCheckPostReformMaintenance = ppCheckPostReformMaintenance

// MIKASA_POLITICAL_POWER_RUNTIME_END

political_power_runtime_ready = 1

!}
go-to: jumpScene

