    return {
        districtId: districtId,
        seats: seats,
        status: status,
        failureFallback: ppDistrictFailureFallback(districtId),
        coalitions: coalitions,
        affordableCoalitions: affordable,
        tolerationOffer: toleration,
        corpMajority: corpMajority,
