// Strip Q assignments at end so we can re-bind
const setupCode = block.replace(/Q\.\w+ = [\s\S]*$/, '')

function runScenario(name, init) {
  const Q = {}
  global.Q = Q
  eval(setupCode)
  init(Q)
  const result = Q.ppEnumeratePlayerCoalitions('district', 'Vats', {})
  console.log('\n=== ' + name + ' ===')
  console.log('Seats: D=' + Q.Vats_D + ' C=' + Q.Vats_C + ' G=' + Q.Vats_G + ' H=' + Q.Vats_H + ' I=' + Q.Vats_I)
  console.log('IG slack: soylent L-R=' + (Q.soylent_leverage - Q.soylent_reprisal) + ', families L-R=' + ((Q.families_leverage||0) - (Q.families_reprisal||0)))
  for (const c of result) {
    const pay = c.payees.map(p => p.ig + ':' + p.seats + ' seats (cost ' + p.cost + ')').join(', ') || 'none'
    console.log('  ' + c.id + ' → total ' + c.seatTotal + ', uses D=' + c.partyUse.D + ' C=' + c.partyUse.C + ' G=' + c.partyUse.G + ' I=' + c.partyUse.I + ', payees: ' + pay + ', affordable=' + c.affordable)
  }
}

