function ppFormatCoalitionPartyLabel(c) {
    var parts = ['D' + c.partyUse.D]
    if (c.partyUse.C > 0) { parts.push('C' + c.partyUse.C) }
    if (c.partyUse.G > 0) { parts.push('G' + c.partyUse.G) }
    if (c.partyUse.I > 0) { parts.push('I' + c.partyUse.I) }
    return parts.join('+') + ' (' + c.seatTotal + ' seats)'
}

function ppFormatCoalitionPayees(c) {
    if (!c.payees || !c.payees.length) { return 'no IG bandwidth cost' }
    var bits = []
    for (var i = 0; i < c.payees.length; i++) {
        var p = c.payees[i]
        bits.push(p.ig + ' (' + p.cost + ' bw)')
    }
    return bits.join(', ')
}

function ppCoalitionBulletsHtml(report) {
    var note = PP_CONTROL_STATUS_NOTE[report.status] || report.status
    var html = '<p><em>' + note + '</em></p>'
    var coalitions = report.coalitions || []
    if (!coalitions.length) {
