function ppElectionSimCoalitionQualityKey(targetId) {
    if (targetId === 'exec') { return 'election_sim_coalitions_exec' }
    return 'election_sim_coalitions_' + targetId
}

function refreshElectionSimCoalitionReports() {
    var opts = { useProjections: true }
    ppEnsureElectionSimIgDefaults()
    Q.election_sim_coalitions_exec = ppCoalitionBulletsHtml(ppCheckExecutiveControl(opts))
    for (var i = 0; i < PP_DISTRICT_IDS.length; i++) {
        var did = PP_DISTRICT_IDS[i]
        Q['election_sim_coalitions_' + did] = ppCoalitionBulletsHtml(ppCheckDistrictControl(did, opts))
    }
}

/** Paint coalition HTML into .election-sim-coalition-slot placeholders (election sim scene). */
function renderElectionSimCoalitionReports() {
    var attempts = 0
    var maxAttempts = 12

    function paint() {
        var nodes = document.querySelectorAll('.election-sim-coalition-slot')
        if (!nodes.length) { return false }
        for (var i = 0; i < nodes.length; i++) {
            var node = nodes[i]
            var target = node.getAttribute('data-coalition-target')
            if (!target) { continue }
            var key = ppElectionSimCoalitionQualityKey(target)
            var html = Q[key]
            if (html == null || html === '') {
                html = '<p><em>Coalition data unavailable</em></p>'
            }
            node.innerHTML = html
        }
        return true
    }

    function tryPaint() {
        if (paint()) { return }
        attempts += 1
        if (attempts < maxAttempts) {
            setTimeout(tryPaint, 0)
        }
    }
    tryPaint()
}

